-- ============================================================================
-- PARTIE 17 — Contenu du module 5 « Observation professionnelle » (3 séquences)
-- Source : Projet pédagogique Koalakids (observer chaque enfant, signes du corps,
-- grilles d'observation, cahier d'équipe, cahier parental, album de l'enfant).
-- Le projet pédagogique n'a pas de section dédiée à l'observation : le module se
-- limite aux passages qui en parlent.
-- Script reconstitué à partir de la base (contenu publié).
-- Relançable : la trame est remplacée, les blocs ne sont ajoutés qu'une fois.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 17.1a Trame de la séquence 1/3 (Apport). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$Observer, c'est prendre le temps de regarder chaque enfant pour comprendre où il en est, avant d'interpréter.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable de dire ce qu'il observe chez un enfant (gestes, regards, signes, paroles) sans l'interpréter trop vite, et de s'en servir pour adapter son accompagnement.", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 2, "attendu": "Observation professionnelle"}, "duree_min": 45, "materiel": ["Paperboard", "Fiche de trace"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Présenter les 3 séances du module : apport, analyse d'une situation vécue, test d'une pratique.", "Chacun pense à un enfant qu'il connaît bien et à un signe qui lui est propre (fatigue, plaisir, malaise), sans le nommer."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "Observer chaque enfant, c'est comprendre où il en est : on regarde avant d'interpréter, puis on interagit.", "idees": ["Chaque enfant a son propre développement : prendre le temps de l'observer permet de comprendre où il se situe sur le plan moteur, langagier et relationnel.", "On porte une attention particulière aux manifestations du corps (gestes, regards, mimiques, crispation, mouvement de recul, position de retrait) ainsi qu'aux paroles. Chaque enfant a aussi ses propres signes de fatigue, comme les bâillements ou les frottements des yeux.", "On prend du recul pour ne pas confondre nos ressentis avec les siens : le jeune enfant ne pense pas le monde comme les adultes. Et observer ne suffit pas : l'adulte interagit ensuite pour soutenir l'enfant, sans le guider."], "support": "Projet pédagogique Koalakids, « Être attentif aux expressions et aux ressentis des enfants »."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site", "consigne": "Choisir un enfant du site, sans le nommer, et décrire ce que l'on a observé cette semaine. On analyse ce que fait l'adulte, pas ce qu'est l'enfant.", "questions": ["Qu'ai-je vu ? (gestes, regards, mimiques, paroles, sans interpréter)", "Qu'est-ce que je crois comprendre, et qu'est-ce que je ne sais pas ?", "Mes propres ressentis ont-ils pu se mêler à ce que j'ai vu ?", "Que faire autrement pour adapter mon accompagnement ?"], "consignes": ["Dans la trace écrite, on n'écrit ni nom d'enfant ni nom de collègue."]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "consigne": "Un engagement concret par personne, à tester pendant la semaine et à raconter à la séance 3.", "amorce": "Cette semaine, je…", "consignes": ["Exemple : observer un enfant pendant cinq minutes et noter ce qu'il fait, sans l'interpréter.", "Exemple : repérer les signes de fatigue propres à un enfant.", "Exemple : décrire un geste ou un regard à un collègue avant de dire ce que j'en pense."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes), sans nom d'enfant.", "Annoncer la séance 2/3 : construire une grille d'observation pour répondre à une question précise sur un enfant."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 5 % 1/3 %';
-- FIN 17.1a

-- ---------------------------------------------------------------------------
-- 17.1b Blocs de la séquence 1/3. Attendu : 5 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "Regarder avant d'interpréter", "paragraphes": ["Chaque enfant a son propre développement, ses propres signes, sa propre façon de dire qu'il est bien ou mal. Pour le comprendre, il faut **prendre le temps de l'observer**.", "Cette première séance pose un repère : on regarde d'abord ce que l'enfant fait et montre, on prend du recul sur ce que l'on ressent soi-même, et seulement ensuite on adapte son accompagnement."]}$kk$),
  (1,'retenir',$kk${"titre": "À retenir", "points": ["**Chaque enfant a son développement propre :** moteur, langagier, relationnel. On l'observe pour comprendre où il en est.", "**Le corps parle :** gestes, regards, mimiques, crispation, mouvement de recul, position de retrait, et aussi paroles.", "**Observer ne suffit pas :** on prend du recul sur nos ressentis, puis on interagit pour soutenir l'enfant sans le guider."]}$kk$),
  (2,'comparaison',$kk${"intro": "Pour observer un enfant.", "plutot": ["Décrire ce que je vois : gestes, regards, mimiques, paroles.", "Prendre le temps d'observer chaque enfant.", "Repérer les signes qui sont propres à chaque enfant.", "Prendre du recul pour ne pas confondre mes ressentis avec les siens."], "eviter": ["Interpréter tout de suite à partir de ce que je ressens.", "Attendre le même rythme de tous les enfants.", "Me limiter à regarder sans jamais interagir.", "Parler de l'enfant comme s'il n'était pas là."]}$kk$),
  (3,'reflexion',$kk${"question": "Pensez à un enfant que vous connaissez bien. Quel signe lui est propre, que vous reconnaissez avant qu'il ne parle ?", "sous_titre": "Il n'y a pas de bonne réponse : on cherche à mettre des mots sur ce que l'on voit.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (4,'essayer',$kk${"label": "À essayer cette semaine", "titre": "Observer cinq minutes", "etapes": [{"titre": "Choisir un enfant.", "texte": "Je m'installe près de lui, sans intervenir dans son jeu."}, {"titre": "Noter ce que je vois.", "texte": "Gestes, regards, mimiques, paroles : les faits, sans interprétation."}, {"titre": "Séparer le vu du ressenti.", "texte": "Je distingue ce que j'ai vu de ce que je crois comprendre."}], "note": "Choisissez un seul de ces gestes et testez-le toute la semaine."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 5 % 1/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 17.1b

-- ---------------------------------------------------------------------------
-- 17.2a Trame de la séquence 2/3 (Analyse d'une situation vécue). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$Une question précise appelle une observation précise : on note des moments et des faits, jamais une étiquette.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable de formuler une question précise sur un enfant du site et de construire ensemble une grille pour l'observer et en partager les résultats.", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 2, "attendu": "Observation professionnelle"}, "duree_min": 45, "materiel": ["Paperboard (pour construire une grille d'observation, sans nom)", "Fiche de trace"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Retour sur la semaine : chacun dit en une phrase ce qu'il a essayé de son engagement « Cette semaine, je… », sans l'évaluer.", "Demander qui apporte la question à observer."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "Pour répondre à une question sur un enfant, on observe des moments précis avec une grille, puis on analyse en équipe.", "idees": ["On peut créer une grille d'observation pour répondre à une question précise de l'équipe ou des parents sur un enfant (par exemple : quels sont les moments où un enfant pleure beaucoup à la crèche ?).", "On note des faits plutôt que des jugements. Une étiquette enferme l'enfant dans une vision de lui-même et renforce son comportement.", "Les observations sont analysées en équipe, puis partagées avec les parents. L'enfant reste un interlocuteur : on ne parle pas de lui entre adultes comme s'il n'existait pas."], "support": "Projet pédagogique Koalakids, « Comment bien communiquer avec les parents dans le cadre du partenariat éducatif »."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site", "consigne": "Choisir une question sur un enfant du site, sans le nommer (par exemple : quels sont les moments où il pleure beaucoup ?). Construire ensemble la grille pour l'observer.", "questions": ["Quelle est notre question, formulée précisément ?", "Quels faits allons-nous noter ? (le moment, ce qui précède, ce que fait l'enfant, ce que fait l'adulte)", "Qui observe, à quels moments, pendant combien de temps ?", "Comment allons-nous partager ce que nous aurons vu, avec l'équipe puis avec les parents ?"], "consignes": ["Dans la trace écrite, on n'écrit ni nom d'enfant ni nom de collègue."]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "consigne": "Un engagement concret par personne, à tester pendant la semaine et à raconter à la séance 3.", "amorce": "Cette semaine, je…", "consignes": ["Exemple : remplir la grille pendant trois moments de la journée.", "Exemple : noter ce qui se passe juste avant le pleur d'un enfant.", "Exemple : reformuler en fait une phrase qui contenait une étiquette."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes), sans nom d'enfant.", "Annoncer la séance 3/3 : retour d'expérience sur la pratique testée, avec un focus sur le partage des observations."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 5 % 2/3 %';
-- FIN 17.2a

-- ---------------------------------------------------------------------------
-- 17.2b Blocs de la séquence 2/3. Attendu : 5 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "Une grille pour une question", "paragraphes": ["Quand l'équipe ou les parents se posent une question sur un enfant, on peut y répondre par une **grille d'observation** : on choisit des moments précis et on note des faits.", "Cette séance propose de construire une grille ensemble, sur une question réelle du site, sans nommer l'enfant."]}$kk$),
  (1,'scenes',$kk${"titre": "Trois situations que vous reconnaîtrez", "items": [{"lettre": "A", "titre": "On lui colle une étiquette", "texte": "À l'équipe, on dit de Jules : « Lui, c'est un pleureur. »", "analyse": "une étiquette enferme l'enfant dans une vision de lui-même et renforce son comportement. Mieux vaut poser une question précise : à quels moments Jules pleure-t-il, et que se passe-t-il juste avant ?"}, {"lettre": "B", "titre": "On interprète ses intentions", "texte": "Une collègue dit de Mila : « Elle fait ça pour attirer l'attention. »", "analyse": "une émotion n'est ni une exagération ni une volonté de manipuler. On décrit les faits : ce que Mila fait, à quel moment, avec qui, et ce que l'adulte fait en réponse."}, {"lettre": "C", "titre": "On parle de lui devant lui", "texte": "Deux collègues discutent de Tom, à côté de lui, sans le regarder.", "analyse": "l'enfant est un interlocuteur, pas un objet de discussion entre adultes. On le fait participer à la conversation, et on partage ce que l'on observe avec ses parents."}]}$kk$),
  (2,'comparaison',$kk${"intro": "Pour répondre à une question sur un enfant.", "plutot": ["Poser une question précise avant d'observer.", "Noter des faits : le moment, ce qui précède, ce que fait l'enfant.", "Analyser les observations ensemble, en équipe.", "Partager les observations avec les parents."], "eviter": ["Mettre une étiquette à l'enfant.", "Dire qu'il fait ça pour manipuler ou attirer l'attention.", "Parler de lui entre adultes sans l'inclure.", "Analyser la personne plutôt que la pratique."]}$kk$),
  (3,'reflexion',$kk${"question": "Quelle question aimeriez-vous résoudre sur un enfant du site ? Quels moments de la journée faudrait-il observer ?", "sous_titre": "Il s'agit de décrire, pas de juger. Personne ne lira votre réponse.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (4,'essayer',$kk${"label": "À essayer pendant l'analyse", "titre": "Les trois lignes de la grille", "etapes": [{"titre": "Le moment.", "texte": "Quand est-ce arrivé, et que se passait-il juste avant ?"}, {"titre": "Ce que fait l'enfant.", "texte": "Gestes, regards, paroles, sans étiquette."}, {"titre": "Ce que fait l'adulte.", "texte": "Ce que j'ai dit ou fait, et ce qui a suivi."}], "note": "On analyse la pratique, jamais la personne."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 5 % 2/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 17.2b

-- ---------------------------------------------------------------------------
-- 17.3a Trame de la séquence 3/3 (Test d'une pratique et retour d'expérience). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$Une observation partagée aide toute l'équipe et les parents à agir en connaissance de cause.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable de dire ce qu'a changé la pratique testée, et l'équipe a choisi une pratique commune pour partager ses observations (cahier d'équipe, cahier parental, album de l'enfant).", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 2, "attendu": "Observation professionnelle"}, "duree_min": 45, "materiel": ["Fiche de trace", "Engagements de la séance 2", "Paperboard"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Chacun relit son engagement de la séance 2 (« Cette semaine, je… »).", "Rappeler la règle : on raconte ce qu'on a fait, on ne se juge pas."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "Une observation partagée aide toute l'équipe et les parents à agir en connaissance de cause.", "idees": ["Chaque professionnel lit chaque jour, à son arrivée et au cours de la journée, le cahier parental et le cahier d'équipe, pour agir en connaissance de cause.", "L'album de l'enfant, ouvert dès la première rencontre avec la famille, est complété régulièrement par l'équipe et par les parents, et laissé en libre accès : il partage découvertes, expériences et apprentissages.", "On peut créer des supports écrits pour partager avec les parents les observations de leur enfant dans le jeu. L'enfant participe au récit de sa journée : il est un interlocuteur, pas un objet de discussion."], "support": "Projet pédagogique Koalakids, « Comment bien communiquer avec les parents dans le cadre du partenariat éducatif »."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site (retour d'expérience)", "consigne": "Chacun raconte en une minute la pratique qu'il a testée. On cherche ce qui s'est passé, pas qui a bien ou mal fait.", "questions": ["Qu'ai-je testé, et dans quelle situation ?", "Qu'est-ce que cela a changé pour l'équipe ou pour les parents, même un peu ?", "Qu'est-ce qui a été difficile ?", "Que gardons-nous en équipe ? Que changeons-nous ?"]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "consigne": "Choisir ensemble une pratique commune à tenir pendant deux semaines, puis un engagement par personne.", "amorce": "Cette semaine, je…", "consignes": ["Pratique commune : une phrase que chacun peut décrire de la même façon.", "Chacun s'engage sur un geste précis, noté sur la fiche de trace."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes), sans nom d'enfant.", "Tour de table : ce que je retiens du module 5. Annoncer le prochain module du programme et la date de la première séance."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 5 % 3/3 %';
-- FIN 17.3a

-- ---------------------------------------------------------------------------
-- 17.3b Blocs de la séquence 3/3. Attendu : 4 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "Faire circuler ce qu'on a vu", "paragraphes": ["Une observation qui reste dans la tête d'une seule personne n'aide personne. Le **cahier d'équipe**, le **cahier parental** et l'**album de l'enfant** servent à partager ce que l'on voit, pour que chacun agisse en connaissance de cause.", "Cette dernière séance sert à regarder ensemble ce que vous avez testé, et à choisir **une pratique commune** pour partager vos observations."]}$kk$),
  (1,'retenir',$kk${"titre": "À retenir", "points": ["**Lire chaque jour** le cahier parental et le cahier d'équipe, à l'arrivée et au cours de la journée.", "**L'album de l'enfant** est complété par l'équipe et les parents, et laissé en libre accès.", "**L'enfant participe** au récit de sa journée : il est un interlocuteur, pas un objet de discussion."]}$kk$),
  (2,'reflexion',$kk${"question": "Qu'est-ce qui vous empêche le plus de lire ou de compléter les cahiers et l'album ? Qu'est-ce qui vous aiderait ?", "sous_titre": "Il n'y a pas de bonne réponse : on cherche ce qui rendrait le partage plus simple.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (3,'essayer',$kk${"label": "À essayer après la séance", "titre": "Une pratique commune", "etapes": [{"titre": "La choisir ensemble.", "texte": "Un geste simple de partage, que chacun fait de la même façon."}, {"titre": "La tenir deux semaines.", "texte": "Sans chercher la perfection : on note ce qui marche et ce qui coince."}, {"titre": "En reparler en équipe.", "texte": "À la prochaine réunion, quelques minutes pour dire ce qu'on garde."}], "note": "Toute pratique commune se décrit en une phrase."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 5 % 3/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 17.3b

-- ---------------------------------------------------------------------------
-- 17c Contrôle (lecture seule). Attendu : 3 séquences, blocs 5 / 5 / 4.
-- ---------------------------------------------------------------------------
select m.titre, m.publie, (m.trame->>'objectif') is not null as objectif_ok,
       (select count(*) from public.bloc b where b.module_id = m.id) as blocs
from public.module m where m.titre like 'Module 5 %/3 %' order by m.ordre;
-- FIN 17c
